def solution(input_data):
    lines = input_data.strip().split('\n')
    idx = 0

    n, m = map(int, lines[idx].split())
    idx += 1
    s, t = map(int, lines[idx].split())
    idx += 1

    edges = []
    adj = [[] for _ in range(n + 1)]

    for i in range(1, m + 1):
        parts = list(map(int, lines[idx].split()))
        idx += 1
        u, v, w = parts
        edges.append((u, v, w, i))
        adj[u].append((v, i))
        adj[v].append((u, i))

    def is_connected(start, end, forbidden_indices):
        """Check if start and end are connected using BFS, avoiding roads with forbidden indices."""
        visited = [False] * (n + 1)
        queue = deque([start])
        visited[start] = True

        while queue:
            u = queue.popleft()
            if u == end:
                return True
            for v, edge_idx in adj[u]:
                if edge_idx <= n and edge_idx not in forbidden_indices:
                    if not visited[v]:
                        visited[v] = True
                        queue.append(v)
        return False

    def remove_edges(edge_indices):
        """Check if removing edges in edge_indices disconnects s and t."""
        forbidden = set(edge_indices)
        # Add road indices (1 to m)
        for (u, v, w, i) in edges:
            forbidden.add(i)
        return not is_connected(s, t, edge_indices)

    # Check if already disconnected
    result = None
    if not is_connected(s, t, set()):
        return "0\n0\n"

    # Try removing 1 road
    min_cost_1 = float('inf')
    best_1 = None

    for i in range(m):
        edge_idx = edges[i][3]
        if remove_edges([edge_idx]):
            if edges[i][2] < min_cost_1:
                min_cost_1 = edges[i][2]
                best_1 = [edge_idx]

    # Try removing 2 roads
    min_cost_2 = float('inf')
    best_2 = None

    for i in range(m):
        for j in range(i + 1, m):
            edge_idx1 = edges[i][3]
            edge_idx2 = edges[j][3]
            if remove_edges([edge_idx1, edge_idx2]):
                cost = edges[i][2] + edges[j][2]
                if cost < min_cost_2:
                    min_cost_2 = cost
                    best_2 = [edge_idx1, edge_idx2]

    if min_cost_1 == float('inf'):
        if min_cost_2 != float('inf'):
            return f"{min_cost_2}\n2\n{' '.join(map(str, best_2))}"
        else:
            return "-1"
    else:
        if min_cost_2 != float('inf') and min_cost_2 < min_cost_1:
            return f"{min_cost_2}\n2\n{' '.join(map(str, best_2))}"
        else:
            return f"{min_cost_1}\n1\n{' '.join(map(str, best_1))}"

