import sys
from collections import Counter

def solution(data):
    # Parse the input
    lines = data.strip().split('\n')
    n = int(lines[0])
    if n == 0:
        return "0"

    # Get all strings
    strings = lines[1:n+1]

    if n == 0:
        return "0"

    # Precompute sorted versions for anagram checking
    sorted_strings = [tuple(sorted(s)) for s in strings]

    total = 0
    for i in range(n):
        for j in range(i + 1, n):
            # Case 1: Strings are equal -> 0 operations
            if strings[i] == strings[j]:
                total += 0
            # Case 2: Strings are anagrams but not equal -> 1 operation (sort one string)
            elif sorted_strings[i] == sorted_strings[j]:
                total += 1
            # Case 3: Not anagrams -> 1337 operations (impossible)
            else:
                total += 1337

    return str(total)

import heapq

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    x = list(map(int, lines[1].split()))
    a, b = map(int, lines[2].split())

    # If a equals b, no moves needed
    if a == b:
        return '0'

    # dist array for values from b to a
    # dist[v - b] stores the minimum moves to reach value v from a
    dist_size = a - b + 1
    dist = [float('inf')] * dist_size
    dist[a - b] = 0

    # Priority queue: (distance, value)
    pq = [(0, a)]

    while pq:
        d, curr = heapq.heappop(pq)

        # If we found a shorter path already, skip
        if d > dist[curr - b]:
            continue

        # If we reached b, return the answer
        if curr == b:
            return str(d)

        # Optimization: if we've already found optimal for all needed values, continue
        if all(dist[i] != float('inf') for i in range(b, b + dist_size)):
            break

        # Operation 1: subtract 1
        next_val = curr - 1
        if next_val >= b:
            new_dist = d + 1
            if new_dist < dist[next_val - b]:
                dist[next_val - b] = new_dist
                heapq.heappush(pq, (new_dist, next_val))

        # Operation 2: subtract (curr mod xi) for each xi
        for xi in x:
            mod_result = curr % xi
            if mod_result > 0:
                next_val = curr - mod_result
                if next_val >= b:
                    new_dist = d + 1
                    if new_dist < dist[next_val - b]:
                        dist[next_val - b] = new_dist
                        heapq.heappush(pq, (new_dist, next_val))

    return str(dist[b - b])

