def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return 'NO'

    n, m = map(int, lines[0].split())
    clauses = []
    for i in range(n):
        parts = list(map(int, lines[i + 1].split()))
        k = parts[0]
        literals = parts[1:]
        clauses.append(literals)

    assignment = [0] * (m + 1)  # 0 = unassigned, 1 = True, -1 = False

    def is_lit_satisfied(lit):
        var = abs(lit)
        sign = 1 if lit > 0 else -1
        if assignment[var] == 0:
            return True
        return assignment[var] * sign > 0

    def is_clause_satisfied(literals):
        for lit in literals:
            if is_lit_satisfied(lit):
                return True
        return False

    changed = True
    while changed:
        changed = False

        for idx, literals in enumerate(clauses):
            if not is_clause_satisfied(literals):
                for lit in literals:
                    var = abs(lit)
                    if assignment[var] == 0:
                        assignment[var] = 1 if lit > 0 else -1
                        changed = True
                        break

        if not changed:
            break

    for literals in clauses:
        if not is_clause_satisfied(literals):
            return 'NO'

    result_str = ''.join(str(assignment[i]) if assignment[i] != 0 else '0' for i in range(1, m + 1))
    return 'YES\n' + result_str


