        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    # Find connected components using BFS
    visited = [False] * (n + 1)
    components = []

    from collections import deque

    for i in range(1, n + 1):
        if not visited[i]:
            comp_size = 0
            queue = deque([i])
            visited[i] = True
            while queue:
                u = queue.popleft()
                comp_size += 1
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        queue.append(v)
            components.append(comp_size)

    # Check if any component size is already lucky
    def is_lucky(x):
        s = str(x)
        return all(c in '47' for c in s)

    for size in components:
        if is_lucky(size):
            return "0\n"

    # Generate all lucky numbers up to n
    lucky_numbers = []
    def generate_lucky(current, max_n):
        if current > max_n:
            return
        if len(current) > 7 or (current == 0 and len(current) >= 9):
            return
        lucky_numbers.append(current)
        generate_lucky(current * 10 + 4, max_n)
        generate_lucky(current * 10 + 7, max_n)

    generate_lucky(0, n)
    lucky_numbers.append(0)
    lucky_numbers = sorted(set(lucky_numbers))

    # For each lucky number, use DP to find minimum components needed
    min_roads = float('inf')

    # Sort components to optimize DP
    components.sort()

    for target in lucky_numbers:
        if target == 0:
            continue
        if target > n:
            break

        # dp[s] = minimum number of components to get sum s
        dp = [float('inf')] * (target + 1)
        dp[0] = 0

        for comp in components:
            if comp >= target:
                break
            # DP with forward iteration since we can use each component at most once
            for s in range(target, comp - 1, -1):
                if dp[s - comp] != float('inf'):
                    dp[s] = min(dp[s], dp[s - comp] + 1)

        if dp[target] != float('inf'):
            min_roads = min(min_roads, dp[target] - 1)  # roads = components - 1

    if min_roads == float('inf'):
        return "-1\n"

    return f"{min_roads}\n"


