    arr = list(map(int, data[1].split()))

    def is_gp(a):
        k = len(a)
        if k <= 2:
            return True
        # Handle all zeros case
        if all(x == 0 for x in a):
            return True
        # Handle prefix of zeros
        zero_count = 0
        while zero_count < k and a[zero_count] == 0:
            zero_count += 1
        # If all were zeros, already handled above
        if zero_count == k:
            return True

        # Non-zero elements must form GP among themselves
        # Find first non-zero element
        first_nonzero = zero_count
        if first_nonzero < k - 1:
            # Ratio from first to second non-zero
            if a[first_nonzero] == 0 or a[first_nonzero + 1] == 0:
                return False
            # Must have consistent ratio from here
            common_ratio = a[first_nonzero + 1] / a[first_nonzero]

            # Check all subsequent elements
            for i in range(first_nonzero, k - 1):
                if a[i] == 0:
                    return False
                expected = a[i] * common_ratio
                if abs(a[i + 1] - expected) > 1e-6:
                    return False
        return True

    # Check if already GP
    if is_gp(arr):
        return '0\n'

    # Try deleting each element
    for i in range(n):
        new_arr = arr[:i] + arr[i+1:]
        if is_gp(new_arr):
            return '1\n'

    return '2\n'

