def solution(s):
    """
    Solves the Lieges of Legendre game theory problem using Grundy numbers (Sprague-Grundy theorem).

    The game is a Nim variant where each pile is independent, and the Grundy number (mex value) 
    of each pile XORed determines the winner.

    States:
    1. Remove 1 cow from a pile
    2. Split even pile 2x into k piles of x

    Returns "Kevin" for first player win (non-zero XOR), "Nicky" for second player win (zero XOR).
    """
    lines = s.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Find maximum pile size we need to handle
    max_a = 0
    for x in a:
        if x > max_a:
            max_a = x

    # Compute Grundy numbers with cycle detection
    grundy_cache = [0]  # G(0) = 0
    cycle_start = 0  # Start index where cycle begins
    cycle = []

    def compute_grundy(num):
        """Computes Grundy number for pile of size num, detecting cycle early."""
        if num == 0:
            return 0

        # Look backward from current position to detect cycle
        while num > cycle_start and len(grundy_cache) > num:
            pass

        # If we've computed this before (within cache limit), return it
        if len(grundy_cache) > num:
            return grundy_cache[num]

        # Compute reachable Grundy values
        reachable = set()

        # Move 1: Remove one cow
        reachable.add(grundy_cache[num - 1])

        # Move 2: Split even pile
        if num % 2 == 0:
            x = num // 2
            # XOR sum of k copies of G(x)
            # If k is odd: XOR = G(x), if k is even: XOR = 0
            if k % 2 == 1:
                reachable.add(grundy_cache[x])
            else:
                reachable.add(0)

        # Find mex (minimum excludant)
        g = 0
        while g in reachable:
            g += 1

        # Store result with cycle detection
        grundy_cache.append(g)

        # Check for cycle - Grundy numbers must eventually become periodic
        # Look back from previous positions to find repetition in the cycle
        for i in range(1, len(grundy_cache) - 1):
            # Check if we found a periodic pattern
            if grundy_cache[i] == grundy_cache[-1] and i > 100:
                # Found potential cycle
                return grundy_cache[-1]

        # Continue computing - for large numbers, pattern stabilizes
        return g

    def get_grundy(num):
        """Get Grundy number with memoization for larger values using pattern detection."""
        if num == 0:
            return 0

        # For small numbers, compute directly
        if num < 200000:  # Cap at reasonable limit
            # Fast direct computation
            memo = {0: 0}

            def compute_x(num):
                if num in memo:
                    return memo[num]

                reachable = set()
                reachable.add(compute_x(num - 1))

                if num % 2 == 0:
                    x = num // 2
                    if k % 2 == 1:
                        reachable.add(compute_x(x))
                    else:
                        reachable.add(0)

                g = 0
                while g in reachable:
                    g += 1

                memo[num] = g
                return g

            return compute_x(num)

        # For very large numbers, use mathematical pattern
        # Based on game analysis, Grundy numbers follow patterns based on (num % some_period)
        # For k odd: G(n) = 0 if n odd, else pattern based on n mod 4 or 6
        # For k even: G(n) = 1 if n odd, else pattern based on n mod 4 or 6

        if k % 2 == 1:  # k is odd
            if num % 2 == 1:  # odd
                if num == 1 or num == 3:
                    return 1
                return 0
            else:  # even
                if num == 0:
                    return 0
                if num % 4 == 0:
                    return 2
                return 1  # num % 4 == 2
        else:  # k is even
            if num % 2 == 1:  # odd
                return 1
            else:  # even
                if num % 4 == 0:
                    return 2
                if num % 4 == 2:
                    return 2 if num % 4 == 2 else 1
                return 1

    # More accurate computational approach for all cases
    memo = {0: 0}

    def grundy_func(n):
        if n in memo:
            return memo[n]

        reachable = set()
        reachable.add(grundy_func(n - 1))  # Remove 1 cow

        if n % 2 == 0:
            x = n // 2
            # If k is odd: XOR of k copies of G(x) = G(x)
            # If k is even: XOR of k copies of G(x) = 0
            if k % 2 == 1:
                reachable.add(grundy_func(x))
            else:
                reachable.add(0)

        g = 0
        while g in reachable:
            g += 1

        memo[n] = g
        return g

    # Compute XOR of all piles
    total_xor = 0
    for pile in a:
        if pile in memo and pile < len(memo):
            total_xor ^= memo[pile]
        else:
            total_xor ^= grundy_func(pile)

    # Check for winning position
    if total_xor != 0:
        return "Kevin\n"
    else:
        return "Nicky\n"

