    # Two fixed adjacent cells should not have the same color
    for i in range(n):
        for j in range(m):
            if grid[i][j] != '0':
                color1 = int(grid[i][j])
                for di in [-1, 0, 1]:
                    for dj in [-1, 0, 1]:
                        if di == 0 and dj == 0:
                            continue
                        ni, nj = i + di, j + dj
                        if 0 <= ni < n and 0 <= nj < m:
                            if grid[ni][nj] != '0' and int(grid[ni][nj]) == color1:
                                return "0"

    # Backtracking function
    result = [row[:] for row in grid]  # Copy of grid

    def is_conflict(i, j, color):
        """Check if assigning 'color' to grid[i][j] would create a conflict"""
        for di in range(-1, 2):
            for dj in range(-1, 2):
                if di == 0 and dj == 0:
                    continue
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < m:
                    if result[ni][nj] != '0' and int(result[ni][nj]) == color:
                        return True
        return False

    def solve(i, j):
        # If we've filled the grid, we're done
        if i == n:
            return True

        # Move to next cell
        if j == m:
            return solve(i + 1, 0)

        # If this cell is pre-colored, move on
        if result[i][j] != '0':
            return solve(i, j + 1)

        # Try each color 1-4
        for color in range(1, 5):
            if not is_conflict(i, j, color):
                result[i][j] = str(color)
                if solve(i, j + 1):
