def square_free_part(n):
    """Get the square-free part of n by dividing out all square factors."""
    result = 1
    if n > 1:
        for i in range(2, int(math.sqrt(n)) + 1):
            while n % (i * i) == 0:
                result *= i
                n //= (i * i)
        if n > 1:
            result *= n
    return result

