def dist2(a, b):
    return sum((ai - bi) ** 2 for ai, bi in zip(a, b))


def max_dist(points, center):
    return max(math.sqrt(dist2(p, center)) for p in points)


def compute_centroid(points):
    n = len(points)
    return [sum(p[i] for p in points) / n for i in range(3)]


