def sphere_from_3(a, b, c):
    d = [b[i] - a[i] for i in range(3)]
    e = [c[i] - a[i] for i in range(3)]

    # Check if collinear (cross product zero)
    cp = [d[1]*e[2] - d[2]*e[1],
          d[2]*e[0] - d[0]*e[2],
          d[0]*e[1] - d[1]*e[0]]

    norm = sum(x*x for x in cp)
    if norm < 1e-12:
        # Collinear, use first 2 points
        return sphere_from_2(a, b)

    # Solve linear system
    # center - a is equidistant from a, b, c
    # 2*d . center = d^2 + a^2 - 2*a . center = ...
    # Actually: ||x - a||^2 = ||x - b||^2 => -2a·x + a^2 = -2b·x + b^2
    # => 2(b-a)·x = b^2 - a^2

    A = [[2*d[0], 2*d[1], 2*d[2]],
         [2*e[0], 2*e[1], 2*e[2]],
         [cp[0], cp[1], cp[2]]]

    A2 = [[A[i][j] for j in range(3)] for i in range(3)]
    b = [0.0, 0.0, 0.0]

    for i in range(3):
        ab = [p[i][0] for p in [a, b, c]]
        bc = [dist2(a, p) for p in [a, b, c]]
        b[i] = (bc[1] - bc[0]) / 2

    try:
        center = zxger(A2, b)
    except:
        center = [(a[0] + (b[0] + c[0])) / 4,
                  (a[1] + (b[1] + c[1])) / 4,
                  (a[2] + (b[2] + c[2])) / 4]

    center = [center[0], center[1], center[2]]
    r2 = dist2(center, a)
    return center, r2


def sphere_from_4(a, b, c, d):
    # Center is equidistant from all 4
    # Solve linear system
    A = []
    b_vec = []

    for i, px in enumerate([a, b, c]):
        for j, py in enumerate([b, c, d]):
            if i < j:
                A.append([2*(px[1]-px[0]), 2*(py[1]-py[0]), 
                         2*(px[2]-px[1])])
        b_vec.append(dist2(b, py) - dist2(a, px))

    if not A or len(A) < 3:
