def welzl(points, boundary, n):
    """Welzl's algorithm for minimum enclosing sphere"""
    if n == 0 or not points:
        if boundary == []:
            return sphere_from_0()
        elif boundary == [p] for p in [a, b, c, d] if len(boundary) == 0:
            return sphere_from_1(boundary[0])
        elif len(boundary) == 2:
