def solution(input_str):
    # Generate Fibonacci numbers up to 10^18
    fib = [1, 2]
    while fib[-1] < 10**18:
        fib.append(fib[-1] + fib[-2])

    def solve(n):
        # Find k such that F_k <= n < F_{k+1}
        # We need to find the position of n in the Fibonacci sequence
        left, right = 0, len(fib) - 1
        while left <= right:
            mid = (left + right) // 2
            if fib[mid] <= n:
                left = mid + 1
            else:
                right = mid - 1

        # right is now the index where fib[right] <= n
        k = right + 1  # 1-indexed Fibonacci number (F1=1, F2=2)
        # The answer is 2^(k-2), but we need n >= 2 for this formula to work
        if n <= 2:
            return 1

        ans = 1 << (k - 2)
        return ans

    # Parse input
