def solution(input_str):
    import sys
    from decimal import Decimal

    MOD = 10**9 + 7
    lines = input_str.strip().split('\n')
    q = int(lines[0])
    queries = []
    for i in range(1, q+1):
        r, n = map(int, lines[i].split())
        queries.append((r, n))

    MAX_N = 1000000
    spf = list(range(MAX_N + 1))
    for i in range(2, int(MAX_N**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, MAX_N + 1, i):
                if spf[j] == j:
                    spf[j] = i

    def get_prime_factors(n):
        factors = {}
        while n > 1:
            p = spf[n]
            cnt = 0
            while n % p == 0:
                n //= p
                cnt += 1
            factors[p] = cnt
        return factors

    def f_r_power(e, r):
        """Compute f_r(p^e) where p is any prime."""
        dp = [0] * (e + 1)
        dp[0] = 1
        for i in range(1, e + 1):
            dp[i] = 2

        for _ in range(r):
            new_dp = [0] * (e + 1)
            for i in range(e + 1):
                for j in range(i + 1):
                    new_dp[i] = (new_dp[i] + dp[j] * dp[i - j]) % MOD
            dp = new_dp

        return dp[e]

    def f_r(n, r):
        if n == 1:
            return 1
        factors = get_prime_factors(n)
        ans = 1
        for e in factors.values():
            ans = (ans * f_r_power(e, r)) % MOD
        return ans

    out = []
    for r, n in queries:
        out.append(str(f_r(n, r)))

    return '\n'.join(out)
